var campaigns=[],statuses={"Email Sent":{color:"#1abc9c",label:"text-bg-success",icon:"fa-envelope"},"Emails Sent":{color:"#1abc9c",label:"text-bg-success",icon:"fa-envelope"},"In progress":{label:"text-bg-primary"},Queued:{label:"text-bg-info"},Completed:{label:"text-bg-success"},"Email Opened":{color:"#f9bf3b",label:"text-bg-warning",icon:"fa-envelope"},"Email Reported":{color:"#45d6ef",label:"text-bg-info",icon:"fa-bullhorn"},"Clicked Link":{color:"#F39C12",label:"text-bg-clicked",icon:"fa-mouse-pointer"},Success:{color:"#f05b4f",label:"text-bg-danger",icon:"fa-exclamation"},Error:{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-times"},"Error Sending Email":{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-times"},"Submitted Data":{color:"#f05b4f",label:"text-bg-danger",icon:"fa-exclamation"},Unknown:{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-question"},Sending:{color:"#428bca",label:"text-bg-primary",icon:"fa-spinner"},"Campaign Created":{label:"text-bg-success",icon:"fa-rocket"}},statsMapping={sent:"Email Sent",opened:"Email Opened",email_reported:"Email Reported",clicked:"Clicked Link",submitted_data:"Submitted Data"};function deleteCampaign(a){confirm("Delete "+campaigns[a].name+"?")&&api.campaignId.delete(campaigns[a].id).done(function(a){successFlash(a.message),location.reload()})}function renderPieChart(a){return GophishCharts.renderDoughnut({elemId:a.elemId,title:a.title,data:a.data,colors:a.colors,centerFontSize:16})}function generateStatsPieCharts(a){var e=[],t={},s=0;$.each(a,function(a,e){$.each(e.stats,function(a,e){if("total"==a)return s+=e,!0;t[a]?t[a]+=e:t[a]=e})}),$.each(t,function(a,t){if(!(a in statsMapping))return!0;status_label=statsMapping[a],e.push({name:status_label,y:Math.floor(t/s*100),count:t}),e.push({name:"",y:100-Math.floor(t/s*100)});renderPieChart({elemId:a+"_chart",title:status_label,name:a,data:e,colors:[statuses[status_label].color,"#dddddd"]});e=[]})}function generateTimelineChart(a){var e=[];$.each(a,function(a,t){var s=moment.utc(t.created_date).local();t.y=0,t.y+=t.stats.clicked,t.y=Math.floor(t.y/t.stats.total*100),e.push({campaign_id:t.id,name:t.name,x:s.valueOf(),y:t.y})}),GophishCharts.renderOverview({elemId:"overview_chart",title:"Phishing Success Overview",data:e})}$(document).ready(function(){api.campaigns.summary().done(function(a){$("#loading").hide(),(campaigns=a.campaigns).length>0?($("#dashboard").show(),campaignTable=$("#campaignTable").DataTable({columnDefs:[{orderable:!1,targets:"no-sort"},{className:"color-sent",targets:[2]},{className:"color-opened",targets:[3]},{className:"color-clicked",targets:[4]},{className:"color-success",targets:[5]},{className:"color-reported",targets:[6]}],order:[[1,"desc"]]}),campaignRows=[],$.each(campaigns,function(a,e){var t=moment(e.created_date).format("MMMM Do YYYY, h:mm:ss a"),s=statuses[e.status].label||"text-bg-secondary";if(moment(e.launch_date).isAfter(moment()))var n="Scheduled to start: "+moment(e.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>Number of recipients: "+e.stats.total;else n="Launch Date: "+moment(e.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>Number of recipients: "+e.stats.total+"<br><br>Emails opened: "+e.stats.opened+"<br><br>Emails clicked: "+e.stats.clicked+"<br><br>Submitted Credentials: "+e.stats.submitted_data+"<br><br>Errors : "+e.stats.error+"<br><br>Reported : "+e.stats.email_reported;campaignRows.push([escapeHtml(e.name),t,e.stats.sent,e.stats.opened,e.stats.clicked,e.stats.submitted_data,e.stats.email_reported,'<span class="badge '+s+'" data-bs-toggle="tooltip" data-bs-placement="right" data-bs-html="true" title="'+n+'">'+e.status+"</span>","<div class='float-end'><a class='btn btn-primary' href='/campaigns/"+e.id+"' data-bs-toggle='tooltip' data-bs-placement='left' title='View Results'>                    <i class='fa fa-bar-chart'></i>                    </a>                    <button class='btn btn-danger' onclick='deleteCampaign("+a+")' data-bs-toggle='tooltip' data-bs-placement='left' title='Delete Campaign'>                    <i class='fa fa-trash-o'></i>                    </button></div>"]),bsInitTooltips()}),campaignTable.rows.add(campaignRows).draw(),generateStatsPieCharts(campaigns),generateTimelineChart(campaigns)):$("#emptyMessage").show()}).fail(function(){errorFlash("Error fetching campaigns")})});